 '')  || COALESCE('bps', '')) WHEN "unit" = 'PERCENTAGE' THEN (COALESCE(CAST(ROUND(case when regexp_like("from_value", '^-?\d+(\.\d*)?$') then cast("from_value" as double) else null end, 1) AS VARCHAR), '')  || COALESCE('%', '')) ELSE (COALESCE(CAST(CAST(truncate(ROUND(case when regexp_like("from_value", '^-?\d+(\.\d*)?$') then cast("from_value" as double) else null end / 1000000, 0)) AS BIGINT) AS VARCHAR), '')  || COALESCE('M', '')) END NULLS FIRST
LIMIT 500

